import { MetricStat } from "@langwatch/charts";

export default function Widget() {
  const { data, isLoading, isError, error } = LW.useChartQuery("main", {});
  if (isError) return <div style={{ fontSize: 11, color: "#b00" }}>{error.message}</div>;
  if (isLoading || data === null) return <div style={{ fontSize: 11, color: "#666" }}>Loading…</div>;
  if (data.length === 0) return <div style={{ fontSize: 11, color: "#666" }}>No data in this window.</div>;

  const total = data.reduce(function (sum, row) { return sum + Number(row.traces || 0); }, 0);

  return (
    <div style={{ height: "100%" }}>
      <MetricStat
        value={total}
        label="Traces (window)"
        format="number"
        sparkline={data}
        sparklineKey="traces"
      />
    </div>
  );
}
